// Draft a sprite with the local image model.
//
// TWO RULES, and using the wrong one produces a confidently wrong picture.
//
// DAEMONS (kind: "creature", the default) follow 9.4: drawn in NEUTRAL GREYS
// with a few saturated accents, coloured at build time from the type ramp --
// "the art stays type-agnostic, so one drawing is correct whatever the type
// is." Asking for a colourful creature yields something gbasprite.py cannot
// use, because the ramp is a parameter and not paint.
//
// PEOPLE (kind: "character" or "overworld") follow 9.4's other half, settled
// 2026-09-06 by generating four treatments and looking at them. The Clears are
// coloured by FAMILY, not by type, so the greys rule is exactly wrong for them
// -- Crystal is a golden fox. THE RULE has three clauses, and each one is a
// treatment that failed:
//
//   1. Animality INTEGRATED, never grafted -- paw hands, a tail, a head
//      proportioned to the body. Never an animal head on a human body; C
//      proved that is a mask no colour-matching repairs.
//   2. Drawn PLAINLY -- flat colour, cel shading, no fur or scale texture, no
//      gloss, no musculature, no fluff. This is the clause that separates
//      fable from furry, and the one A got wrong.
//   3. Head-to-body ratio carries AGE -- large head for children, small for
//      adults. Left unstated everyone comes out cute, which nearly broke
//      Scorn.
//
// "overworld" adds the framing an overworld frame needs. It still returns a
// 384px illustration: a real frame is 16x32 and a sheet is 144x32 for nine of
// them, so this is REFERENCE TO DRAW FROM, never a shippable sprite.
const req = $input.first().json, headers = req.headers || {}, body = req.body || {};
const expected = $env.DEX_SHARED_SECRET;
if (expected && headers['x-dex-secret'] !== expected) throw new Error('Unauthorized: bad or missing x-dex-secret');

const kind = String(body.kind || 'creature').toLowerCase();
if (!['creature', 'character', 'overworld'].includes(kind)) {
  throw new Error(`Unknown kind '${kind}'. Use creature, character or overworld.`);
}

const name = String(body.name || (kind === 'creature' ? 'creature' : 'person'));
const idea = String(body.idea || '');
let prompt;

if (kind === 'creature') {
  const accent = String(body.accent || '');
  prompt = [
    `pixel art sprite of ${name}${idea ? ', ' + idea : ''}`,
    `drawn in NEUTRAL GREYS only -- light grey, mid grey, dark grey, near-black outline`,
    accent ? `with a single small ${accent} as the only colour` : `with no colour anywhere`,
    `front-facing, centred, full body, thick near-black outline, flat shading, no gradients`,
    `plain white background, no text, no border, no shadow on the ground`,
  ].join(', ');
} else {
  // species is the ROLE, not decoration: "Aesop's fox is not a character who
  // happens to be a fox -- he is a fox because the story needs cunning."
  const species = String(body.species || 'fox');
  const wearing = String(body.wearing || '');
  const age = String(body.age || 'adult').toLowerCase();
  const ratio = age === 'child' || age === 'young'
    ? 'child proportions, large head relative to the body'
    : 'adult proportions, small head relative to the body';
  const framing = kind === 'overworld'
    ? 'overworld game sprite, standing and facing the viewer straight on, full body, feet visible, symmetrical stance'
    : 'full body character reference, facing the viewer, relaxed stance';

  prompt = [
    `${ratio} ${species} character named ${name}${idea ? ', ' + idea : ''}`,
    wearing ? `wearing ${wearing}` : '',
    `funny-animal fable style in the tradition of Carl Barks, Disney's Robin Hood and Redwall`,
    `animality INTEGRATED not grafted: ${species} head proportioned to the body, paw hands, a tail`,
    `NOT an animal head on a human body, NOT a mask, NOT a costume`,
    `drawn PLAINLY: flat colour, cel shading, thick dark outline`,
    `NO fur texture, NO scale texture, no gloss, no highlights, no musculature, no fluff`,
    framing,
    `plain white background, no text, no border`,
  ].filter(Boolean).join(', ');
}

return [{ json: { kind, bonsaiBody: { prompt, steps: 4, guidance: 1.0, width: 384, height: 384 } } }];

// Bonsai returns raw PNG bytes; base64 for the caller, like the dex icon flow.
// `kind` is echoed so the caller can tell WHICH rule drew it -- a creature in
// greys and a character in colour are both correct, and confusing them is the
// mistake this parameter exists to prevent.
const kind = ($('Validate + Build Prompt').first().json || {}).kind || null;
let spriteBase64 = null;
try { const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
      if (buf && buf.length) spriteBase64 = buf.toString('base64'); } catch (e) {}
return [{ json: { kind, spriteBase64, spriteMime: spriteBase64 ? 'image/png' : null,
                  error: spriteBase64 ? null : 'generation_failed' } }];
